import java.time.Instant; import java.util.UUID; import jakarta.persistence.*; import edu.pe.cibertec.saibm.membresia.domain.event.MembershipEvent;
@Entity @Table(name="membership_outbox") public class OutboxJpaEntity {@Id UUID eventId;String eventType;int eventVersion;Instant occurredAt;String correlationId;String causationId;String producer;@Column(columnDefinition="text")String payloadJson;boolean published;protected OutboxJpaEntity(){}OutboxJpaEntity(MembershipEvent e,String json){eventId=e.eventId();eventType=e.eventType();eventVersion=e.eventVersion();occurredAt=e.occurredAt();correlationId=e.correlationId();causationId=e.causationId();producer=e.producer();payloadJson=json;}public String getEventType(){return eventType;}public String getPayloadJson(){return payloadJson;}public void published(){published=true;}}
